def install(db):
    owner = db.execute("SELECT id FROM users WHERE username='sana_demo_business' AND demo=1").fetchone()
    if not owner:
        return
    existing = {json.loads(row['body']).get('example_key') for row in db.execute('SELECT body FROM tasks')}
    for example in EXAMPLES:
        if example['key'] in existing:
            continue
        task = {k:v for k,v in example.items() if k != 'key'}
        task.update(example_key=example['key'], owner_id=owner['id'], demo=True, published=True, confirmed=True, original=example['context'])
        db.execute('INSERT INTO tasks(body) VALUES (?)', (json.dumps(task, ensure_ascii=False),))
